SELECT DIV_RVC_RATE        AS rvcRate
      ,DIV_DE_MINIMIS_RATE AS deMinimisRate
FROM   DIVISION
WHERE  COMPANY_CODE = #{companyCode}
AND    DIVISION_CODE = #{divisionCode}

SELECT COM_RVC_RATE        AS rvcRate
      ,COM_DE_MINIMIS_RATE AS deMinimisRate
FROM   FTA_MASTER
WHERE  FTA_CODE = #{ftaCode}
AND    COMPANY_CODE = #{companyCode}

SELECT NATION_CODE
FROM   FTA_APPLY_NATION
WHERE  FTA_CODE = #{ftaCode}

mapper.insert:
INSERT INTO FCR_RESULT (SEQ, SALES_NO, SALES_SEQ, FTA_CODE, DIVISION_CODE, COMPANY_CODE, HS_CODE, PRODUCT_CODE, STANDARD, RULE_SEQ, RULE_CODE, FTA_COO_YN, COMPANY_COO_YN, BUFFER_OPTION, DE_MINIMIS_RATE, RVC_RATE, STATUS, ERROR_CODE, ERROR_MSG, DELETE_YN, CREATE_DATE, CREATE_BY, UPDATE_DATE, UPDATE_BY, SP_COO_YN, WO_COO_YN, CTC_YN, FTA_DE_MINIMIS_YN, COMPANY_DE_MINIMIS_YN, FTA_RVC_YN, COMPANY_RVC_YN, EXCLUSION_YN, EXCLUSION_CONDITION, CTC_RESULT_RATE, CTC_FTA_RESULT_RATE, CTC_COMPANY_RESULT_RATE, RVC_RESULT_RATE, RVC_FTA_RESULT_RATE, RVC_COMPANY_RESULT_RATE, RCEP_COO_NATION) SELECT NS.BASE_SEQ + ROW_NUMBER() OVER (), V.* FROM (
SELECT #{rec.salesNo} AS SALES_NO, #{rec.salesSeq} AS SALES_SEQ, #{rec.ftaCode} AS FTA_CODE, #{rec.divisionCode} AS DIVISION_CODE, #{rec.companyCode} AS COMPANY_CODE, #{rec.hsCode} AS HS_CODE, #{rec.productCode} AS PRODUCT_CODE, #{rec.standard} AS STANDARD, #{rec.ruleSeq} AS RULE_SEQ, #{rec.ruleCode} AS RULE_CODE, #{rec.ftaCooYn} AS FTA_COO_YN, #{rec.companyCooYn} AS COMPANY_COO_YN, #{rec.bufferOption} AS BUFFER_OPTION, #{rec.deMinimisRate} AS DE_MINIMIS_RATE, #{rec.rvcRate} AS RVC_RATE, #{rec.status} AS STATUS, #{rec.errorCode} AS ERROR_CODE, #{rec.errorMsg} AS ERROR_MSG, #{rec.deleteYn} AS DELETE_YN, CURRENT_TIMESTAMP AS CREATE_DATE, #{rec.createBy} AS CREATE_BY, CURRENT_TIMESTAMP AS UPDATE_DATE, #{rec.updateBy} AS UPDATE_BY, #{rec.spCooYn} AS SP_COO_YN, #{rec.woCooYn} AS WO_COO_YN, #{rec.ctcYn} AS CTC_YN, #{rec.ftaDeMinimisYn} AS FTA_DE_MINIMIS_YN, #{rec.companyDeMinimisYn} AS COMPANY_DE_MINIMIS_YN, #{rec.ftaRvcYn} AS FTA_RVC_YN, #{rec.companyRvcYn} AS COMPANY_RVC_YN, #{rec.exclusionYn} AS EXCLUSION_YN, #{rec.exclusionCondition} AS EXCLUSION_CONDITION, #{rec.ctcResultRate} AS CTC_RESULT_RATE, #{rec.ctcFtaResultRate} AS CTC_FTA_RESULT_RATE, #{rec.ctcCompanyResultRate} AS CTC_COMPANY_RESULT_RATE, #{rec.rvcResultRate} AS RVC_RESULT_RATE, #{rec.rvcFtaResultRate} AS RVC_FTA_RESULT_RATE, #{rec.rvcCompanyResultRate} AS RVC_COMPANY_RESULT_RATE, #{rec.rcepCooNation} AS RCEP_COO_NATION
) V CROSS JOIN (SELECT COALESCE(MAX(SEQ), 0) AS BASE_SEQ FROM FCR_RESULT) NS

mapper.select:
SELECT 
FROM   FCR_RESULT FRD
WHERE  FRD.SALES_NO = #{salesNo}
AND    FRD.SALES_SEQ = #{salesSeq}
AND    FRD.FTA_CODE = #{ftaCode}
AND    FRD.DIVISION_CODE = #{divisionCode}
AND    FRD.COMPANY_CODE = #{companyCode}
AND    FRD.COMPANY_COO_YN = 'Y'

SELECT 
FROM   FCR_RESULT FRD
WHERE  FRD.SALES_NO = #{salesNo}
AND    FRD.SALES_SEQ = #{salesSeq}
AND    FRD.FTA_CODE = #{ftaCode}
AND    FRD.DIVISION_CODE = #{divisionCode}
AND    FRD.COMPANY_CODE = #{companyCode}
AND    FRD.COMPANY_COO_YN = 'N'
AND    FRD.STATUS = 'N'

SELECT V.SALES_SEQ AS reqSalesSeq ,V.FTA_CODE AS reqFtaCode ,V.DIVISION_CODE AS reqDivisionCode ,R.* FROM (
SELECT #{r.salesSeq} AS SALES_SEQ, #{r.ftaCode} AS FTA_CODE, #{r.divisionCode} AS DIVISION_CODE
) V LEFT JOIN LATERAL (SELECT * FROM ( (SELECT ,'Y' AS matchTier FROM FCR_RESULT FRD WHERE FRD.SALES_NO = #{salesNo} AND FRD.SALES_SEQ = V.SALES_SEQ AND FRD.FTA_CODE = V.FTA_CODE AND FRD.DIVISION_CODE = V.DIVISION_CODE AND FRD.COMPANY_CODE = #{companyCode} AND FRD.COMPANY_COO_YN = 'Y' FETCH FIRST 1 ROW ONLY) UNION ALL (SELECT ,'N' AS matchTier FROM FCR_RESULT FRD WHERE FRD.SALES_NO = #{salesNo} AND FRD.SALES_SEQ = V.SALES_SEQ AND FRD.FTA_CODE = V.FTA_CODE AND FRD.DIVISION_CODE = V.DIVISION_CODE AND FRD.COMPANY_CODE = #{companyCode} AND FRD.COMPANY_COO_YN = 'N' AND FRD.STATUS = 'N' FETCH FIRST 1 ROW ONLY) ) TIERS ORDER BY matchTier DESC FETCH FIRST 1 ROW ONLY) R ON TRUE

mapper.update:
UPDATE FCR_MST FM SET RULE_CONTENTS = V.RULE_CONTENTS ,FTA_COO_YN = V.FTA_COO_YN ,COMPANY_COO_YN = V.COMPANY_COO_YN ,RCEP_COO_NATION = V.RCEP_COO_NATION FROM (
SELECT #{r.salesNo} AS SALES_NO, #{r.salesSeq} AS SALES_SEQ, #{r.ftaCode} AS FTA_CODE, #{r.divisionCode} AS DIVISION_CODE, #{r.companyCode} AS COMPANY_CODE, #{r.ruleContents} AS RULE_CONTENTS, #{r.ftaCooYn} AS FTA_COO_YN, #{r.companyCooYn} AS COMPANY_COO_YN, #{r.rcepCooNation} AS RCEP_COO_NATION
) V WHERE FM.SALES_NO = V.SALES_NO AND FM.SALES_SEQ = V.SALES_SEQ AND FM.FTA_CODE = V.FTA_CODE AND FM.DIVISION_CODE = V.DIVISION_CODE AND FM.COMPANY_CODE = V.COMPANY_CODE
